class LRUCache:
    """
    A class for LRU Cache that uses a hash map for quick access to values and a list to maintain the order 
    of usage for keys, allowing efficient eviction of the least recently used key when the capacity is reached.
    """

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.order = []

    def get(self, key: int) -> int:
        if key in self.cache:
            self.order.remove(key)
            self.order.append(key)
            return self.cache[key]
        return -1

    def put(self, key: int, value: int) -> None:
        if key in self.cache:
            self.cache[key] = value
            self.order.remove(key)
            self.order.append(key)
        else:
            if len(self.cache) >= self.capacity:
                lru_key = self.order.pop(0)  # Remove the least recently used key
                del self.cache[lru_key]
            self.cache[key] = value
            self.order.append(key)
